//! What the jobs of a service run on: a periodic task that stops cleanly.
//!
//! @generated by service-builder. Do not edit: changes are overwritten on the next export.

use std::future::Future;
use std::time::Duration;

use tokio::sync::watch;
use tokio::task::JoinHandle;
use tokio::time::{MissedTickBehavior, interval};

/// Runs `job` now, then every `every`. After a slow run the missed ticks are not made up for in a burst: the
/// next run simply waits a full period. A failing run is logged and never stops the loop. The loop ends when
/// `shutdown` turns `true`: a run in progress finishes first.
pub fn spawn_periodic<F, Fut, E>(
    name: impl Into<String>,
    every: Duration,
    mut shutdown: watch::Receiver<bool>,
    job: F,
) -> JoinHandle<()>
where
    F: Fn() -> Fut + Send + 'static,
    Fut: Future<Output = Result<(), E>> + Send,
    E: std::fmt::Display,
{
    let name = name.into();
    tokio::spawn(async move {
        let mut ticker = interval(every);
        ticker.set_missed_tick_behavior(MissedTickBehavior::Delay);
        loop {
            if *shutdown.borrow() {
                break;
            }
            tokio::select! {
                _ = ticker.tick() => match job().await {
                    Ok(()) => tracing::debug!(job = %name, "job done"),
                    Err(e) => tracing::warn!(job = %name, error = %e, "job failed"),
                },
                _ = shutdown.changed() => break,
            }
        }
    })
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::sync::Arc;
    use std::sync::atomic::{AtomicU32, Ordering};

    fn counting_job(
        runs: &Arc<AtomicU32>,
        outcome: Result<(), String>,
    ) -> impl Fn() -> std::future::Ready<Result<(), String>> + Send + 'static {
        let runs = runs.clone();
        move || {
            runs.fetch_add(1, Ordering::SeqCst);
            std::future::ready(outcome.clone())
        }
    }

    #[tokio::test(start_paused = true)]
    async fn runs_at_start_then_every_period_and_stops_on_shutdown() {
        let runs = Arc::new(AtomicU32::new(0));
        let (stop, rx) = watch::channel(false);
        let handle = spawn_periodic("tick", Duration::from_secs(60), rx, counting_job(&runs, Ok(())));
        tokio::time::sleep(Duration::from_secs(150)).await;
        // t = 0, 60, 120
        assert_eq!(runs.load(Ordering::SeqCst), 3);
        stop.send(true).unwrap();
        handle.await.unwrap();
        tokio::time::sleep(Duration::from_secs(300)).await;
        assert_eq!(runs.load(Ordering::SeqCst), 3, "no run after the stop");
    }

    #[tokio::test(start_paused = true)]
    async fn a_failing_job_does_not_kill_the_loop() {
        let runs = Arc::new(AtomicU32::new(0));
        let (stop, rx) = watch::channel(false);
        let handle = spawn_periodic(
            "broken",
            Duration::from_secs(10),
            rx,
            counting_job(&runs, Err("database unavailable".into())),
        );
        tokio::time::sleep(Duration::from_secs(25)).await;
        assert_eq!(runs.load(Ordering::SeqCst), 3);
        stop.send(true).unwrap();
        handle.await.unwrap();
    }

    #[tokio::test(start_paused = true)]
    async fn a_slow_run_is_not_made_up_for_in_a_burst() {
        let runs = Arc::new(AtomicU32::new(0));
        let (stop, rx) = watch::channel(false);
        let counter = runs.clone();
        // Each run takes 3.5 periods.
        let handle = spawn_periodic("slow", Duration::from_secs(10), rx, move || {
            let counter = counter.clone();
            async move {
                counter.fetch_add(1, Ordering::SeqCst);
                tokio::time::sleep(Duration::from_secs(35)).await;
                Ok::<(), String>(())
            }
        });
        tokio::time::sleep(Duration::from_secs(80)).await;
        // Runs at 0, 35 (missed ticks are delayed, not replayed), 70: three, not eight.
        let n = runs.load(Ordering::SeqCst);
        assert!((2..=3).contains(&n), "{n} runs");
        stop.send(true).unwrap();
        handle.await.unwrap();
    }

    #[tokio::test(start_paused = true)]
    async fn a_stop_before_the_first_run_means_no_run() {
        let runs = Arc::new(AtomicU32::new(0));
        let (stop, rx) = watch::channel(false);
        stop.send(true).unwrap();
        let handle = spawn_periodic("never", Duration::from_secs(1), rx, counting_job(&runs, Ok(())));
        handle.await.unwrap();
        assert_eq!(runs.load(Ordering::SeqCst), 0);
    }
}
